{
  "name": "@tder311/opencode-orchestrator",
  "version": "0.1.0",
  "description": "Spawn and supervise parallel opencode agents in cmux tabs, each on its own git worktree",
  "type": "module",
  "main": "src/index.js",
  "license": "MIT",
  "author": "Tom Derrick",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/tder311/opencode-orchestrator.git"
  },
  "homepage": "https://github.com/tder311/opencode-orchestrator#readme",
  "bugs": {
    "url": "https://github.com/tder311/opencode-orchestrator/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "cmux",
    "orchestrator",
    "multi-agent",
    "worktree",
    "agents"
  ],
  "engines": {
    "node": ">=18"
  },
  "files": [
    "src",
    "profile",
    "commands",
    "install.sh",
    "orchestrator.json",
    "README.md",
    "AGENTS.md",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "test": "node --test test/*.test.js"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.15.13"
  }
}
